package org.owasp.webgoat.lessons.challenges.challenge5;

import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;

import org.hamcrest.CoreMatchers;
import org.junit.jupiter.api.Test;
import org.owasp.webgoat.container.plugins.LessonTest;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
import org.owasp.webgoat.lessons.challenges.Flags;

class Assignment5Test extends LessonTest {

  @Autowired private Flags flags;

  @Test
  void sqlInjectionShouldNotBypassAuthentication() throws Exception {
    // TAINTED_PTR: user input is concatenated directly into SQL query string (line 44-49)
    // The fix is to use proper parameterized queries with PreparedStatement.setXXX()
    // This test asserts that SQL injection should NOT work — i.e., a malicious password
    // like "' OR '1'='1" should fail authentication, not bypass it.
    // Currently this FAILS because the concatenation allows injection to succeed.
    mockMvc
        .perform(
            MockMvcRequestBuilders.post("/challenge/5")
                .param("username_login", "Larry")
                .param("password_login", "' OR '1'='1"))
        .andExpect(jsonPath("$.lessonCompleted", CoreMatchers.is(false)))
        .andExpect(jsonPath("$.feedback", CoreMatchers.not(CoreMatchers.containsString("flag: " + flags.getFlag(5)))));
  }
}

